mapper.insert:
INSERT INTO separation_policies (
    company_id, default_notice_days, probation_notice_days,
    allow_resignation_withdrawal, auto_deactivate_user,
    require_manager_approval, require_it_clearance, require_finance_clearance
) VALUES (
    #{companyId}, #{defaultNoticeDays}, #{probationNoticeDays},
    #{allowResignationWithdrawal}, #{autoDeactivateUser},
    #{requireManagerApproval}, #{requireItClearance}, #{requireFinanceClearance}
)

mapper.select:
SELECT sc.id, sc.company_id AS companyId, sc.employee_id AS employeeId, sc.case_type AS caseType, sc.initiator_role AS initiatorRole, sc.initiator_user_id AS initiatorUserId, sc.reason_category AS reasonCategory, sc.reason_details AS reasonDetails, sc.submission_date AS submissionDate, sc.requested_last_working_day AS requestedLastWorkingDay, sc.approved_last_working_day AS approvedLastWorkingDay, sc.notice_period_days AS noticePeriodDays, sc.is_notice_waived AS isNoticeWaived, sc.notice_shortfall_days AS noticeShortfallDays, sc.status, sc.handover_notes AS handoverNotes, sc.manager_approval_status AS managerApprovalStatus, sc.manager_remarks AS managerRemarks, sc.manager_reviewed_at AS managerReviewedAt, sc.manager_reviewed_by AS managerReviewedBy, sc.hr_approval_status AS hrApprovalStatus, sc.hr_remarks AS hrRemarks, sc.hr_reviewed_at AS hrReviewedAt, sc.hr_reviewed_by AS hrReviewedBy, sc.exit_interview_completed AS exitInterviewCompleted, sc.exit_interview_notes AS exitInterviewNotes, sc.user_deactivated_at AS userDeactivatedAt, sc.finalized_by AS finalizedBy, sc.finalized_at AS finalizedAt, sc.created_at AS createdAt, sc.updated_at AS updatedAt, e.employee_code AS employeeCode, e.first_name AS firstName, e.last_name AS lastName, e.work_email AS workEmail, d.name AS departmentName, des.title AS designationTitle, TRIM(CONCAT(mgr.first_name, ' ', mgr.last_name)) AS reportingManagerName FROM separation_cases sc JOIN employees e ON e.id = sc.employee_id LEFT JOIN departments d ON d.id = e.department_id LEFT JOIN designations des ON des.id = e.designation_id LEFT JOIN employees mgr ON mgr.id = e.reporting_manager_id WHERE sc.company_id = #{companyId}
AND sc.status = #{status}
AND sc.employee_id = #{employeeId}
ORDER BY sc.created_at DESC

