    #{status}, #{clearedByUserId}, #{clearedAt}, #{deductionAmount}, #{remarks}
)

mapper.update:
UPDATE users
SET is_active = FALSE, updated_at = NOW()
WHERE employee_id = #{employeeId} AND company_id = #{companyId}
